class ResourceOwner {
    int* heavy_data = nullptr;
public:
    // Ctor: Acquire resource
    ResourceOwner(size_t s) : heavy_data(new int[s]) {}
    // Dtor: Release resource
    ~ResourceOwner() { delete[] heavy_data; }

    // Disable copy
    ResourceOwner(const ResourceOwner&) = delete;

    // Move Constructor: Steal resource (Transfer ownership)
    ResourceOwner(ResourceOwner&& other) noexcept
        : heavy_data(other.heavy_data)
    {
        // MOVED-FROM STATE (Valid but empty/unspecified):
        // Nullify source pointer so its destructor is safe.
        other.heavy_data = nullptr;
    }
};

